<section class="mx-auto max-w-4xl px-5 py-12"><a class="text-sm text-neutral-500" href="/dashboard">← Kembali ke dashboard</a><p class="eyebrow mt-8">PANEL ADMIN · PESANAN #<?= (int)$order['id'] ?></p><h1 class="mt-2 text-4xl font-semibold tracking-tight"><?= e($order['title']) ?></h1><div class="mt-8 grid gap-4 sm:grid-cols-2"><div class="rounded-xl border border-line bg-white p-5"><p class="eyebrow">PELANGGAN</p><p class="mt-2 font-medium"><?= e($order['customer_name']) ?></p><p class="text-sm text-neutral-500"><?= e($order['customer_email']) ?></p></div><div class="rounded-xl border border-line bg-white p-5"><p class="eyebrow">LAYANAN · <?= money($order['price']) ?></p><p class="mt-2 font-medium"><?= e($order['service_name']) ?></p><p class="text-sm text-neutral-500">Target: <?= $order['deadline']?e(date('d M Y',strtotime($order['deadline']))):'Fleksibel' ?></p></div></div><article class="mt-4 rounded-xl border border-line bg-white p-6"><p class="eyebrow">BRIEF</p><p class="mt-4 whitespace-pre-line text-sm leading-7"><?= e($order['brief']) ?></p></article><form class="mt-4 flex flex-wrap items-end gap-3 rounded-xl border border-line bg-white p-5" method="post" action="/admin/orders/<?= (int)$order['id'] ?>/status"><?= csrf_field() ?><label class="flex-1 text-sm">Perbarui status<select class="field mt-2" name="status"><?php foreach(['new','review','in_progress','revision','completed','cancelled'] as $s): ?><option value="<?= e($s) ?>" <?= $order['status']===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach ?></select></label><button class="rounded-full bg-ink px-6 py-3 text-sm text-white">Simpan status</button></form></section>
